schema_ddl:
CREATE TABLE magazzini (
    id INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    nome TEXT NOT NULL,
    citta TEXT NOT NULL,
    capacita_max NUMERIC(10,2) CHECK (capacita_max > 0)
);

CREATE TABLE consegne (
    id INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    magazzino_id INT NOT NULL REFERENCES magazzini(id),
    data_consegna DATE NOT NULL,
    peso_totale NUMERIC(10,2) CHECK (peso_totale > 0),
    stato_consegna TEXT NOT NULL
);
